package com.sakti.banking.controller; import com.sakti.banking.dto.*; import com.sakti.banking.service.UserService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController {private final UserService users;public AuthController(UserService u){users=u;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public UserResponse register(@Valid @RequestBody RegisterRequest r){return users.register(r);} @GetMapping("/me") public UserResponse me(Authentication a){return UserResponse.from(users.requireByEmail(a.getName()));} @PutMapping("/profile") public UserResponse profile(Authentication a,@Valid @RequestBody ProfileUpdateRequest r){return users.updateProfile(a.getName(),r);} }
